"""Deterministic policy engine for the travel environment.

All rules are hard-coded and return structured results.
Tool handlers consult these functions before executing mutations.
"""

from datetime import datetime, timedelta
from typing import Any


def check_cancellation_policy(
    cabin_class: str,
    booked_at: str,
    now: str,
    has_insurance: bool,
    airline_cancelled: bool = False,
    price_paid: int = 0,
    route_type: str = "domestic",
) -> dict[str, Any]:
    """Check if a booking can be cancelled and compute the refund.

    Rules:
    - Airline-initiated cancellation: full refund regardless of cabin class
    - Within free cancellation window (24h domestic, 48h international): full refund
    - basic_economy after window: not cancellable (unless insured)
    - economy after window: domestic max($50, 15%), international max($75, 20%)
    - business after window: domestic 5%, international 8%
    - first after window: free cancellation
    - Insurance overrides: if insured, full refund regardless
    """
    if airline_cancelled:
        return {"eligible": True, "fee": 0, "reason": "Airline-initiated cancellation: full refund"}

    booked = datetime.fromisoformat(booked_at)
    current = datetime.fromisoformat(now)

    free_window_hours = 48 if route_type == "international" else 24
    within_window = (current - booked) < timedelta(hours=free_window_hours)

    if within_window:
        return {
            "eligible": True,
            "fee": 0,
            "reason": f"Within {free_window_hours}-hour free cancellation window",
        }

    if has_insurance:
        return {"eligible": True, "fee": 0, "reason": "Travel insurance covers cancellation"}

    if cabin_class == "basic_economy":
        return {
            "eligible": False,
            "fee": 0,
            "reason": f"Basic economy fares cannot be cancelled after the {free_window_hours}-hour window",
        }
    elif cabin_class == "economy":
        if route_type == "international":
            fee = max(75, int(price_paid * 0.20))
            return {
                "eligible": True,
                "fee": fee,
                "reason": f"International economy cancellation fee: max($75, 20% of ${price_paid}) = ${fee}",
            }
        else:
            fee = max(50, int(price_paid * 0.15))
            return {
                "eligible": True,
                "fee": fee,
                "reason": f"Economy cancellation fee: max($50, 15% of ${price_paid}) = ${fee}",
            }
    elif cabin_class == "business":
        if route_type == "international":
            fee = int(price_paid * 0.08)
            return {
                "eligible": True,
                "fee": fee,
                "reason": f"International business cancellation fee: 8% of ${price_paid} = ${fee}",
            }
        else:
            fee = int(price_paid * 0.05)

def load(cls, path: Optional[str] = None) -> "FlightDB":
    """Build the scoped tau2 airline tree from the unified world.db.

    `path` is accepted for back-compat (the old db.json seed) but ignored;
    data is read from world.db (see CUGA_WORLD_DB). Flights/reservations are
    scoped by `source_skill='tau2Airline'`; users by `skill_ids_json`.
    """
    conn = _connect()
    try:
        flights: Dict[str, Any] = {}
        for r in conn.execute(
            "SELECT * FROM flights WHERE source_skill=?", (SOURCE_SKILL,)
        ):
            flights[r["flight_id"]] = {
                "flight_number": r["flight_id"],
                "origin": r["origin"],
                "destination": r["destination"],
                "scheduled_departure_time_est": r["departure_time"],
                "scheduled_arrival_time_est": r["arrival_time"],
                "dates": json.loads(r["dates_json"] or "{}"),
            }

        # Reservation ids per user (User.reservations is derived, not stored).
        resv_by_user: Dict[str, list] = {}
        reservations: Dict[str, Any] = {}
        for r in conn.execute(
            "SELECT * FROM flight_bookings WHERE source_skill=?", (SOURCE_SKILL,)
        ):
            res_flights = []
            for fj in json.loads(r["flights_json"] or "[]"):
                res_flights.append(
                    {
                        "flight_number": fj.get("flight_number") or fj.get("flight_id"),
                        "origin": fj.get("origin", ""),
                        "destination": fj.get("destination", ""),
                        "date": fj.get("date", ""),
                        "price": fj.get("price", 0),
                    }
                )
            reservations[r["booking_id"]] = {
                "reservation_id": r["booking_id"],
                "user_id": r["user_id"],
                "origin": r["origin"],
                "destination": r["destination"],
                "flight_type": r["flight_type"] if r["flight_type"] in _TAU2_FLIGHT_TYPES else "one_way",
                "cabin": r["cabin_class"] if r["cabin_class"] in _TAU2_CABINS else "economy",
                "flights": res_flights,
                "passengers": json.loads(r["passengers_json"] or "[]"),
                "payment_history": json.loads(r["payment_history_json"] or "[]"),
                "created_at": r["booked_at"],
                "total_baggages": r["total_baggages"],
                "nonfree_baggages": r["nonfree_baggages"],
                "insurance": r["add_insurance"] if r["add_insurance"] in ("yes", "no") else "no",
                "status": "cancelled" if r["status"] == "cancelled" else None,
            }
            resv_by_user.setdefault(r["user_id"], []).append(r["booking_id"])

        users: Dict[str, Any] = {}
        for r in conn.execute(
            "SELECT * FROM users WHERE skill_ids_json LIKE ?",
            (f'%"{SOURCE_SKILL}"%',),
        ):
            users[r["user_id"]] = {
                "user_id": r["user_id"],
                "name": _split_name(r["name"]),
                "address": json.loads(r["address_json"] or "{}"),
                "email": r["email"],
                "dob": r["dob"] or "",
                "payment_methods": json.loads(r["payment_methods_json"] or "{}"),
                "saved_passengers": json.loads(r["saved_passengers_json"] or "[]"),
                "membership": _TIER_TO_MEMBERSHIP.get(r["loyalty_tier"], r["loyalty_tier"]),
                "reservations": resv_by_user.get(r["user_id"], []),
            }
    finally:
        conn.close()
    return cls.model_validate(
        {"flights": flights, "users": users, "reservations": reservations}
    )

def save(self, path: Optional[str] = None) -> None:
    """Write mutations back to the unified world.db (scoped to this skill).

    `path` is accepted for back-compat but ignored. Persists per-date flight
    availability (seat/price changes from bookings), user payment methods, and
    the reservation rows (upserted by id so new bookings are captured).
    """
    conn = _connect()
    try:
        cur = conn.cursor()
        for fn, flight in self.flights.items():
            cur.execute(
                "UPDATE flights SET dates_json=? WHERE flight_id=? AND source_skill=?",
                (json.dumps({d: s.model_dump() for d, s in flight.dates.items()}), fn, SOURCE_SKILL),
            )
